/* Basic PPT editing tools for the courseware prototype. */
(function(){
  const style=document.createElement('style');style.textContent=`
  .cw-canvas-tools{display:flex;gap:5px;flex-wrap:wrap;margin:-4px 0 6px;padding:6px 7px;border:1px solid #e3efed;border-radius:8px;background:#f7fbfa}.cw-tool{border:1px solid transparent;border-radius:6px;background:transparent;color:#47706e;padding:6px 8px;font-size:11px;cursor:pointer}.cw-tool:hover,.cw-tool.active{background:#e7f7f4;border-color:#9edbd3;color:#087c72}.cw-shape-picker{height:28px;border:1px solid #d7e8e5;border-radius:6px;background:#fff;color:#47706e;font-size:11px;padding:0 5px}.cw-format-tools{display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin:0 0 9px;padding:6px 7px;border:1px solid #e3efed;border-radius:8px;background:#fff;font-size:10px}.cw-format-tools label{display:inline-flex;align-items:center;gap:4px;color:#6b8582}.cw-format-tools select,.cw-format-tools input{height:26px;border:1px solid #d7e8e5;border-radius:5px;background:#fff;color:#174746;font-size:11px}.cw-format-tools input[type=number]{width:48px;padding:0 4px}.cw-format-tools input[type=color]{width:28px;padding:2px}.cw-added-element{min-width:100px;min-height:34px;padding:8px 10px;border:1px dashed #82cfc5;border-radius:7px;background:#f2fbf9;color:#26766f;font-size:12px}.cw-shape-element{width:88px;height:58px;display:grid;place-items:center;border:2px solid #5bb8ac;border-radius:10px;background:#e9f8f5;color:#19766d;font-size:11px}.cw-circle-element{border-radius:50%}.cw-diamond-element{transform:rotate(45deg);border-radius:5px}.cw-diamond-element span{transform:rotate(-45deg)}.cw-photo-element{width:150px;height:86px;display:grid;place-items:center;overflow:hidden;border:1px dashed #d3a768;border-radius:8px;background:#fff8eb;color:#a16c2b;font-size:11px;text-align:center}.cw-photo-element img{width:100%;height:100%;object-fit:cover}.cw-movable{cursor:grab;user-select:none}.cw-movable.cw-dragging{opacity:.55;cursor:grabbing}.cw-selected{outline:2px solid #18a895!important;outline-offset:3px}.cw-resize-handle{display:none;position:absolute;width:8px;height:8px;background:#fff;border:2px solid #18a895;border-radius:2px;z-index:4}.cw-selected .cw-resize-handle{display:block}.cw-resize-handle.nw{left:-6px;top:-6px;cursor:nwse-resize}.cw-resize-handle.ne{right:-6px;top:-6px;cursor:nesw-resize}.cw-resize-handle.sw{left:-6px;bottom:-6px;cursor:nesw-resize}.cw-resize-handle.se{right:-6px;bottom:-6px;cursor:nwse-resize}.cw-text-editing{cursor:text!important;outline:2px solid #65c5b7!important}.cw-chapter-bar-prep .prep-chapter-pill.active{background:#e8f8f4!important;border:2px solid #35ab9a!important;box-shadow:0 0 0 3px rgba(53,171,154,.18),0 5px 12px rgba(53,171,154,.14)!important;transform:translateY(-2px);position:relative;z-index:2}.cw-chapter-bar-prep .prep-chapter-pill.active b,.cw-chapter-bar-prep .prep-chapter-pill.active small,.cw-chapter-bar-prep .prep-chapter-pill.active i{color:#146f66!important}`;document.head.appendChild(style);
  let undoStack=[],redoStack=[];const canvas=()=>document.querySelector('.cw-real-slide');const snap=()=>{const c=canvas();return c?c.innerHTML:''};const toast=t=>window.cwApply&&window.cwApply(t);const selected=()=>document.querySelector('.cw-real-slide .cw-selected');
  const push=()=>{const s=snap();if(s&&undoStack[undoStack.length-1]!==s){undoStack.push(s);if(undoStack.length>30)undoStack.shift()}redoStack=[]};
  const makeHandle=cls=>{const h=document.createElement('span');h.className='cw-resize-handle '+cls;h.contentEditable='false';return h};
  function enterText(el){if(el.classList.contains('cw-shape-element')||el.classList.contains('cw-photo-element'))return;el.contentEditable='true';el.classList.add('cw-text-editing');el.focus();const r=document.createRange();r.selectNodeContents(el);r.collapse(false);const s=getSelection();s.removeAllRanges();s.addRange(r)}
  function bind(c){c.querySelectorAll(':scope > *:not(.cw-edit-hint)').forEach((el,i)=>{if(el.dataset.toolReady)return;el.dataset.toolReady='1';el.classList.add('cw-movable');el.style.position='absolute';el.style.margin='0';if(!el.style.left)el.style.left='28px';if(!el.style.top)el.style.top=(i*56+22)+'px';if(el.tagName==='H2'||el.tagName==='LI'||el.classList.contains('cw-added-element'))el.classList.add('cw-text-element');['nw','ne','sw','se'].forEach(k=>el.appendChild(makeHandle(k)));el.addEventListener('dblclick',e=>{if(!e.target.classList.contains('cw-resize-handle'))enterText(el)});el.addEventListener('blur',()=>{el.contentEditable='false';el.classList.remove('cw-text-editing')},true);el.addEventListener('pointerdown',e=>{if(e.button!==0||e.target.classList.contains('cw-resize-handle')||el.classList.contains('cw-text-editing'))return;e.preventDefault();e.stopPropagation();push();document.querySelectorAll('.cw-selected').forEach(x=>x.classList.remove('cw-selected'));el.classList.add('cw-selected');const r=c.getBoundingClientRect(),er=el.getBoundingClientRect(),ox=e.clientX-er.left,oy=e.clientY-er.top;const move=ev=>{el.style.left=Math.max(8,Math.min(r.width-el.offsetWidth-8,ev.clientX-r.left-ox))+'px';el.style.top=Math.max(8,Math.min(r.height-el.offsetHeight-8,ev.clientY-r.top-oy))+'px'};const up=()=>{el.releasePointerCapture?.(e.pointerId);el.removeEventListener('pointermove',move);el.removeEventListener('pointerup',up);toast('元素位置已更新')};el.setPointerCapture?.(e.pointerId);el.addEventListener('pointermove',move);el.addEventListener('pointerup',up)});el.querySelectorAll('.cw-resize-handle').forEach(h=>h.addEventListener('pointerdown',e=>{e.preventDefault();e.stopPropagation();push();el.classList.add('cw-selected');const r=c.getBoundingClientRect(),er=el.getBoundingClientRect(),start={x:e.clientX,y:e.clientY,w:er.width,h:er.height,l:parseFloat(el.style.left)||0,t:parseFloat(el.style.top)||0},corner=h.className.split(' ')[1];const move=ev=>{let w=start.w,hg=start.h,l=start.l,t=start.t,dx=ev.clientX-start.x,dy=ev.clientY-start.y;if(corner.includes('e'))w+=dx;if(corner.includes('s'))hg+=dy;if(corner.includes('w')){w-=dx;l+=dx}if(corner.includes('n')){hg-=dy;t+=dy}el.style.width=Math.max(36,w)+'px';el.style.height=Math.max(24,hg)+'px';el.style.left=Math.max(8,Math.min(r.width-w-8,l))+'px';el.style.top=Math.max(8,Math.min(r.height-hg-8,t))+'px'};const up=()=>{el.releasePointerCapture?.(e.pointerId);el.removeEventListener('pointermove',move);el.removeEventListener('pointerup',up);toast('元素大小已更新')};el.setPointerCapture?.(e.pointerId);el.addEventListener('pointermove',move);el.addEventListener('pointerup',up)}))})}
  function add(kind){const c=canvas();if(!c)return;push();const el=document.createElement('div');el.className=kind==='photo'?'cw-photo-element':kind==='text'?'cw-added-element cw-text-element':'cw-shape-element '+(kind==='circle'?'cw-circle-element':kind==='diamond'?'cw-diamond-element':'');el.style.position='absolute';el.style.left='42%';el.style.top='48%';if(kind==='text'){el.textContent='双击编辑文本';el.contentEditable='false'}else if(kind==='photo'){el.textContent='双击选择照片'}else{const s=document.createElement('span');s.textContent=kind==='circle'?'圆形':kind==='diamond'?'菱形':'矩形';el.appendChild(s)}c.appendChild(el);bind(c);el.classList.add('cw-selected');if(kind==='photo')el.addEventListener('dblclick',()=>{const input=document.createElement('input');input.type='file';input.accept='image/*';input.onchange=()=>{const file=input.files&&input.files[0];if(!file)return;const img=document.createElement('img');img.src=URL.createObjectURL(file);el.replaceChildren(img,...['nw','ne','sw','se'].map(makeHandle));toast('照片已替换为预览')};input.click()});toast(kind==='text'?'已添加文本框':kind==='photo'?'已添加照片占位':`已添加${kind==='circle'?'圆形':kind==='diamond'?'菱形':'矩形'}`)}
  window.cwFormat=function(type,value){const c=canvas(),el=selected();if(type==='bg'&&c){push();c.style.background=value;return toast('PPT 背景颜色已更新')}if(type==='font'||type==='size'||type==='color'){push();const targets=[...c.querySelectorAll('.cw-text-element,.cw-slide-kicker,.cw-diagram,.cw-diagram *')];targets.forEach(x=>{if(type==='font')x.style.fontFamily=value;if(type==='size')x.style.fontSize=value+'px';if(type==='color')x.style.color=value});return toast('已应用到全部文本元素')}if(!el)return toast('请先选择一个元素')};
  window.cwTool=function(btn,kind){document.querySelectorAll('.cw-tool').forEach(x=>x.classList.remove('active'));btn.classList.add('active');if(kind!=='select')add(kind)};window.cwUndo=function(){const c=canvas();if(!c||!undoStack.length)return toast('暂无可撤销操作');redoStack.push(c.innerHTML);c.innerHTML=undoStack.pop();bind(c);toast('已撤销')};window.cwRedo=function(){const c=canvas();if(!c||!redoStack.length)return toast('暂无可恢复操作');undoStack.push(c.innerHTML);c.innerHTML=redoStack.pop();bind(c);toast('已恢复')};window.cwCopy=function(){const el=selected();if(!el)return toast('请先选择一个元素');push();const n=el.cloneNode(true);n.dataset.toolReady='';n.style.left=(parseFloat(el.style.left||'30')+18)+'px';n.style.top=(parseFloat(el.style.top||'30')+18)+'px';n.querySelectorAll('.cw-resize-handle').forEach(x=>x.remove());el.parentElement.appendChild(n);bind(el.parentElement);toast('已复制选中元素')};window.cwDelete=function(){const el=selected();if(!el)return toast('请先选择一个元素');push();el.remove();toast('已删除选中元素')};
  function install(){const c=canvas();if(!c||c.dataset.toolsInstalled)return;c.dataset.toolsInstalled='1';bind(c);const tools=document.createElement('div');tools.className='cw-canvas-tools';tools.innerHTML='<button class="cw-tool active" onclick="cwTool(this,\'select\')">↖ 选择</button><button class="cw-tool" onclick="cwTool(this,\'text\')">T 文本</button><label><select class="cw-shape-picker" onchange="if(this.value){cwTool(this, this.value);this.value=\'\'}"><option value="">＋ 添加形状</option><option value="shape">矩形</option><option value="circle">圆形</option><option value="diamond">菱形</option><option value="triangle">三角形</option><option value="line">直线</option></select></label><button class="cw-tool" onclick="cwTool(this,\'photo\')">▣ 照片</button><button class="cw-tool" onclick="cwCopy()">⧉ 复制</button><button class="cw-tool" onclick="cwDelete()">⌫ 删除</button><button class="cw-tool" onclick="cwUndo()">↶ 撤销</button><button class="cw-tool" onclick="cwRedo()">↷ 恢复</button>';c.before(tools);const fmt=document.createElement('div');fmt.className='cw-format-tools';fmt.innerHTML='<label>字体<select onchange="cwFormat(\'font\',this.value)"><option>Microsoft YaHei</option><option>Arial</option><option>Georgia</option><option>Courier New</option></select></label><label>字号<input type="number" min="8" max="72" value="16" onchange="cwFormat(\'size\',this.value)"></label><label>文字色<input type="color" value="#174746" onchange="cwFormat(\'color\',this.value)"></label><label>背景<input type="color" value="#fbfefd" onchange="cwFormat(\'bg\',this.value)"></label>';tools.after(fmt)}
  document.addEventListener('keydown',e=>{if(!canvas())return;const tag=(e.target.tagName||'').toLowerCase();if(e.key==='Escape'){document.querySelectorAll('.cw-text-editing').forEach(x=>{x.contentEditable='false';x.classList.remove('cw-text-editing')});document.querySelectorAll('.cw-selected').forEach(x=>x.classList.remove('cw-selected'));return}if(['input','textarea','select'].includes(tag)||e.target.isContentEditable)return;if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();window.cwDelete()}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?window.cwRedo():window.cwUndo()}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){e.preventDefault();window.cwRedo()}});
  const obs=new MutationObserver(install);obs.observe(document.body,{childList:true,subtree:true});window.addEventListener('hashchange',()=>setTimeout(install,50));setTimeout(install,100);
  const slideDeleteStyle=document.createElement('style');slideDeleteStyle.textContent='.cw-thumb .thumb-top{position:relative;align-items:center}.cw-thumb-delete{border:0;background:transparent;color:#a1b6b3;font-size:16px;line-height:1;padding:0 2px;cursor:pointer;opacity:0}.cw-thumb:hover .cw-thumb-delete,.cw-thumb.active .cw-thumb-delete{opacity:1}.cw-thumb-delete:hover{color:#c65050}';document.head.appendChild(slideDeleteStyle);
})();
